  occupiedRooms: ACCOMMODATION_ROOMS.filter(r => !r.isAvailable).length,
  occupancyRate: Math.round((ACCOMMODATION_ROOMS.filter(r => !r.isAvailable).length / ACCOMMODATION_ROOMS.length) * 100)
