export const getPriceStats = () => ({
  lowest: Math.min(...ACCOMMODATION_ROOMS.map(r => r.pricePerNight)),
  highest: Math.max(...ACCOMMODATION_ROOMS.map(r => r.pricePerNight)),
  average: Math.round(ACCOMMODATION_ROOMS.reduce((sum, r) => sum + r.pricePerNight, 0) / ACCOMMODATION_ROOMS.length),
  median: (() => {
    const sorted = ACCOMMODATION_ROOMS.map(r => r.pricePerNight).sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
  })()
});

